import{_ as c,l as t,o as s,c as d,v as o,p,x as a,d as l,i,S as n}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"proc 与 sysfs","description":"","frontmatter":{"title":"proc 与 sysfs","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sysfs-proc.md","filePath":"cs/sysfs-proc.md","lastUpdated":1789023840000}'),f={name:"cs/sysfs-proc.md"};function h(_,e,u,m,y,b){const r=t("Mermaid");return s(),d("div",null,[e[1]||(e[1]=o('<h1 id="proc-与-sysfs" tabindex="-1">proc 与 sysfs <a class="header-anchor" href="#proc-与-sysfs" aria-label="Permalink to &quot;proc 与 sysfs&quot;">​</a></h1><div class="epigraph"><p>proc 把进程与若干内核表格导出成文件；sysfs 按设备模型把 kobject 树导出成属性文件。</p><footer>—— 据 Linux proc(5)/sysfs 文档；Love 对 kobject 的整理</footer></div><p><a href="/cs/kernel-module">上一课</a>注册了设备，用户还没有可移植的「查看与微调」接口。<a href="/cs/vfs">VFS</a> 允许没有块设备的伪文件系统。<a href="/cs/mount-super">挂载</a> 已提 proc。缺口是把 <strong>proc 与 sysfs</strong> 收成两棵树：一个偏进程与杂项，一个偏设备模型。读它们走普通 <code>read</code>，实现是回调填缓冲。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若只有 <code>ioctl</code> 魔数，工具无法用 cat/grep。proc：<code>/proc/self/maps</code>、<code>stat</code>、sysctl 风格的 <code>/proc/sys</code>。历史堆积使 proc 变杂。sysfs：一设备一目录，属性一文件，与 kobject 生命周期绑在一起，热插拔时目录出现消失。缺口不是新的 inode 磁盘格式，而是 <code>show</code>/<code>store</code> 回调与权限。</p><p>本课不把每个 <code>/proc</code> 文件列成清单。</p><p><span class="marginnote">sysfs 属性通常短、一值一文。大块二进制不该放 sysfs。debugfs 是第三棵调试树，主干点名即可。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>内核挂载 <code>proc</code>、<code>sysfs</code>。lookup 生成 inode；<code>read</code> 调 show，把当前 jiffies、模块列表、队列深度等格式化进页。<a href="/cs/page-cache">页缓存</a> 对它们往往是临时的。写 sysfs 可能改参数，须权限检查。模块在 init 里创建属性，exit 里删除，避免悬空。</p>',9)),(s(),p(n,null,{default:a(()=>[i(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20OPEN%5B%22open%20%2Fproc%20%E6%88%96%20%2Fsys%22%5D%20--%3E%20CB%5B%22show%2Fstore%20%E5%9B%9E%E8%B0%83%22%5D%0A%20%20CB%20--%3E%20BUF%5B%22%E7%94%9F%E6%88%90%E6%96%87%E6%9C%AC%22%5D%0A%20%20BUF%20--%3E%20USER%5B%22%E7%94%A8%E6%88%B7%20read%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>伪文件系统让「内核状态」复用文件抽象，shell 与监控工具不必新系统调用。它们不是真实持久：崩溃一致性课的日志与此无关。过度读 <code>/proc</code> 可能有开销（每次生成）。不要把 sysfs 写成攻击面扫描教程。</p><p>与 dcache 的关系：这些 dentry 常是动态的，lookup 时创建。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 netlink 的全部通用套接字。不保证 ABI 文本格式永不改变。下一课问：这些文件系统出现之前，机器如何从复位走到能 <code>mount</code> 的内核。</p><p>后课默认：运行中的内核可经文件查询。从引导加载器到 <code>start_kernel</code>，下一课早期启动。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>proc 偏进程与 sysctl；sysfs 偏 kobject 设备树。</li><li>读写是回调，不是磁盘块。</li><li>复位之后如何进入内核，是 early-boot 的缺口。</li><li>出处：Linux <code>proc(5)</code>、sysfs 文档；Love, <em>LKD</em>。</li></ul>',8))])}const x=c(f,[["render",h]]);export{E as __pageData,x as default};
